#include "parallel_letter_frequency.h"

#include <cctype>
#include <thread>
#include <vector>

namespace parallel_letter_frequency {

frequency frequency(const std::vector<std::string>& texts,
                    unsigned int workers)
{
    if (texts.empty()) {
        return {};
    }

    const auto worker_count =
        std::max(1u, std::min(workers, static_cast<unsigned int>(texts.size())));

    std::vector<frequency> partial_frequencies(worker_count);
    std::vector<std::thread> threads;
    threads.reserve(worker_count);

    for (unsigned int worker = 0; worker < worker_count; ++worker) {
        const auto begin =
            static_cast<std::size_t>(worker) * texts.size() / worker_count;
        const auto end =
            static_cast<std::size_t>(worker + 1) * texts.size() / worker_count;

        threads.emplace_back([&, worker, begin, end] {
            auto& partial = partial_frequencies[worker];

            for (std::size_t text_index = begin; text_index < end; ++text_index) {
                for (const auto character : texts[text_index]) {
                    const auto unsigned_character =
                        static_cast<unsigned char>(character);

                    if (std::isalpha(unsigned_character)) {
                        const auto lowercase =
                            static_cast<char>(std::tolower(unsigned_character));
                        ++partial[lowercase];
                    }
                }
            }
        });
    }

    for (auto& thread : threads) {
        thread.join();
    }

    frequency result;

    for (const auto& partial : partial_frequencies) {
        for (const auto& entry : partial) {
            result[entry.first] += entry.second;
        }
    }

    return result;
}

}
